    assert payload["schema"] == "ask.setup.v1"
    assert payload["status"] == "dry-run"
    assert payload["profile"] == "local-dev"
    assert payload["used_interview"] is False
    assert payload["start_missing_requested"] is False
    assert payload["start_missing_services"] is False
    assert payload["explicit_start_consent"] is False
    assert payload["actions"] == []
    assert config_path.exists() is False


